8	namespace MediaWiki\Watchlist;
9	
10	use MediaWiki\Language\MessageLocalizer;
11	use MediaWiki\Page\PageReference;
12	use MediaWiki\RecentChanges\RecentChange;
13	use MediaWiki\User\UserIdentity;
14	use MediaWiki\Utils\MWTimestamp;
15	use Wikimedia\ParamValidator\TypeDef\ExpiryDef;
16	use Wikimedia\Timestamp\ConvertibleTimestamp;
17	use Wikimedia\Timestamp\TimestampFormat as TS;
18	
19	/**
20	 * Representation of a pair of user and title for watchlist entries.
21	 *
22	 * @author Tim Starling
23	 * @author Addshore
24	 *
25	 * @ingroup Watchlist
26	 */
27	class WatchedItem {
28		/**
29		 * @var PageReference
30		 */
31		private $target;
32	
33		/**
34		 * @var UserIdentity
35		 */
36		private $user;
37	
38		/**
39		 * @var bool|null|string the value of the wl_notificationtimestamp field
40		 */
41		private $notificationTimestamp;
42	
43		/**
44		 * @var ConvertibleTimestamp|null value that determines when a watched item will expire.
45		 *  'null' means that there is no expiration.
46		 */
47		private $expiry;
48	
49		/**
50		 * @var WatchlistLabel[]
51		 */
52		private $labels;
53	
54		/**
55		 * Used to calculate how many days are remaining until a watched item will expire.
56		 * Uses a different algorithm from Language::getDurationIntervals for calculating
57		 * days remaining in an interval of time
58		 *
59		 * @since 1.35
60		 */
61		private const SECONDS_IN_A_DAY = 86400;
62	
63		/**
64		 * @param UserIdentity $user
65		 * @param PageReference $target
66		 * @param bool|null|string $notificationTimestamp the value of the wl_notificationtimestamp field
67		 * @param null|string $expiry Optional expiry timestamp in any format acceptable to wfTimestamp()
68		 * @param WatchlistLabel[] $labels
69		 */
70		public function __construct(
71			UserIdentity $user,
72			PageReference $target,
73			$notificationTimestamp,
74			?string $expiry = null,
75			array $labels = []
76		) {
77			$this->user = $user;
78			$this->target = $target;
79			$this->notificationTimestamp = $notificationTimestamp;
80	
81			// Expiry will be saved in ConvertibleTimestamp
82			$this->expiry = ExpiryDef::normalizeExpiry( $expiry );
83	
84			// If the normalization returned 'infinity' then set it as null since they are synonymous
85			if ( $this->expiry === 'infinity' ) {
86				$this->expiry = null;
87			}
88	
89			$this->labels = $labels;
90		}
91	
92		/**
93		 * @since 1.35
94		 * @param RecentChange $recentChange
95		 * @param UserIdentity $user
96		 * @return WatchedItem
97		 */
98		public static function newFromRecentChange( RecentChange $recentChange, UserIdentity $user ) {
99			return new self(
100				$user,
101				$recentChange->getTitle(),
102				$recentChange->notificationtimestamp,
103				$recentChange->watchlistExpiry
104			);
105		}
106	
107		/**
108		 * @return UserIdentity
109		 */
110		public function getUserIdentity() {
111			return $this->user;
112		}
113	
114		/**
115		 * @return PageReference
116		 * @since 1.36
117		 */
118		public function getTarget() {
119			return $this->target;
120		}
121	
122		/**
123		 * Get the notification timestamp of this entry.
124		 *
125		 * @return bool|null|string
126		 */
127		public function getNotificationTimestamp() {
128			return $this->notificationTimestamp;
129		}
130	
131		/**
132		 * When the watched item will expire.
133		 *
134		 * @since 1.35
135		 * @param int|TS|null $style Given timestamp format to style the ConvertibleTimestamp
136		 * @return string|null null or in a format acceptable to ConvertibleTimestamp (TS::* constants).
137		 *  Default is TS::MW format.
138		 */
139		public function getExpiry( int|TS|null $style = TS::MW ) {
140			return $this->expiry instanceof ConvertibleTimestamp
141				? $this->expiry->getTimestamp( $style )
142				: $this->expiry;
143		}
144	
145		/**
146		 * Has the watched item expired?
147		 *
148		 * @since 1.35
149		 *
150		 * @return bool
151		 */
152		public function isExpired(): bool {
153			$expiry = $this->getExpiry();
154			if ( $expiry === null ) {
155				return false;
156			}
157			return $expiry < ConvertibleTimestamp::now();
158		}
159	
160		/**
161		 * Get days remaining until a watched item expires.
162		 *
163		 * @since 1.35
164		 *
165		 * @return int|null days remaining or null if no expiration is present
166		 */
167		public function getExpiryInDays(): ?int {
168			return self::calculateExpiryInDays( $this->getExpiry() );
169		}
170	
171		/**
172		 * Get the number of days remaining until the given expiry time.
173		 *
174		 * @since 1.35
175		 *
176		 * @param string|null $expiry The expiry to calculate from, in any format
177		 * supported by MWTimestamp::convert().
178		 *
179		 * @return int|null The remaining number of days or null if $expiry is null.
180		 */
181		public static function calculateExpiryInDays( ?string $expiry ): ?int {
182			if ( $expiry === null ) {
183				return null;
184			}
185	
186			$unixTimeExpiry = (int)MWTimestamp::convert( TS::UNIX, $expiry );
187			$diffInSeconds = $unixTimeExpiry - (int)ConvertibleTimestamp::now( TS::UNIX );
188			$diffInDays = $diffInSeconds / self::SECONDS_IN_A_DAY;
189	
190			if ( $diffInDays < 1 ) {
191				return 0;
192			}
193	
194			return (int)floor( $diffInDays );
195		}
196	
197		/**
198		 * Get days remaining until a watched item expires as a text.
199		 *
200		 * @since 1.35
201		 * @param MessageLocalizer $msgLocalizer
202		 * @param bool $isDropdownOption Whether the text is being displayed as a dropdown option.
203		 *             The text is different as a dropdown option from when it is used in other
204		 *             places as a watchlist indicator.
205		 * @return string days remaining text and '' if no expiration is present
206		 */
207		public function getExpiryInDaysText( MessageLocalizer $msgLocalizer, $isDropdownOption = false ): string {
208			$expiryInDays = $this->getExpiryInDays();
209			if ( $expiryInDays === null ) {
210				return '';
211			}
212	
213			if ( $expiryInDays < 1 ) {
214				if ( $isDropdownOption ) {
215					return $msgLocalizer->msg( 'watchlist-expiry-hours-left' )->text();
216				}
217				return $msgLocalizer->msg( 'watchlist-expiring-hours-full-text' )->text();
218			}
219	
220			if ( $isDropdownOption ) {
221				return $msgLocalizer->msg( 'watchlist-expiry-days-left' )->numParams( $expiryInDays )->text();
222			}
223	
224			return $msgLocalizer->msg( 'watchlist-expiring-days-full-text' )->numParams( $expiryInDays )->text();
225		}
226	
227		/**
228		 * Get labels associated with a watched item
229		 *
230		 * @since 1.46
231		 * @return WatchlistLabel[]
232		 */
233		public function getLabels(): array {
234			return $this->labels;
235		}
236	}
237	/** @deprecated class alias since 1.43 */
238	class_alias( WatchedItem::class, 'WatchedItem' );
