192			$userIdentity = $performer->getUser();
193			$userTalkPage = (
194				$title->getNamespace() === NS_USER_TALK &&
195				$title->getDBkey() === strtr( $userIdentity->getName(), ' ', '_' )
196			);
197	
198			if ( $userTalkPage ) {
199				if ( !$oldid ) {
200					$oldRev = null;
201				} elseif ( !$oldRev ) {
202					$oldRev = $this->revisionLookup->getRevisionById( $oldid );
203				}
204				// NOTE: Has to be called before isAllowed() check, to ensure users with no watchlist
205				// access (by default, temporary and anonymous users) can clear their talk page
206				// notification (T345031).
207				$this->talkPageNotificationManager->clearForPageView( $userIdentity, $oldRev );
208			}
209	
210			if ( !$this->isEnotifEnabled ) {
211				return;
212			}
213	
214			if ( !$userIdentity->isRegistered() ) {
215				// Nothing else to do
216				return;
217			}
218	
219			// NOTE: Has to be checked after the TalkPageNotificationManager::clearForPageView call, to
220			// ensure users with no watchlist access (by default, temporary and anonymous users) can
221			// clear their talk page notification (T345031).
222			if ( !$performer->isAllowed( 'editmywatchlist' ) ) {
223				// User isn't allowed to edit the watchlist
224				return;
225			}
226	
227			// Only update the timestamp if the page is being watched.
228			// The query to find out if it is watched is cached both in memcached and per-invocation,
229			// and when it does have to be executed, it can be on a replica DB
230			// If this is the user's newtalk page, we always update the timestamp
231			$force = $userTalkPage ? 'force' : '';
232			$this->watchedItemStore->resetNotificationTimestamp( $userIdentity, $title, $force, $oldid );
233		}
