235		/**
236		 * Get the timestamp when this page was updated since the user last saw it.
237		 *
238		 * @param UserIdentity $user
239		 * @param PageReference $title
240		 * @return string|bool|null String timestamp, false if not watched, null if nothing is unseen
241		 */
242		public function getTitleNotificationTimestamp( UserIdentity $user, PageReference $title ) {
243			if ( !$user->isRegistered() ) {
244				return false;
245			}
246	
247			$cacheKey = 'u' . $user->getId() . '-' .
248				$title->getNamespace() . ':' . $title->getDBkey();
249	
250			// avoid isset here, as it'll return false for null entries
251			if ( array_key_exists( $cacheKey, $this->notificationTimestampCache ) ) {
252				return $this->notificationTimestampCache[ $cacheKey ];
253			}
254	
255			$watchedItem = $this->watchedItemStore->getWatchedItem( $user, $title );
256			if ( $watchedItem ) {
257				$timestamp = $watchedItem->getNotificationTimestamp();
258			} else {
259				$timestamp = false;
260			}
261	
262			$this->notificationTimestampCache[ $cacheKey ] = $timestamp;
263			return $timestamp;
264		}
