342		/**
343		 * Watch a page. Calls the WatchArticle and WatchArticleComplete hooks.
344		 * @since 1.37
345		 * @param UserIdentity $userIdentity
346		 * @param PageReference $target
347		 * @param string|null $expiry Optional expiry timestamp in any format acceptable to wfTimestamp(),
348		 *   null will not create expiries, or leave them unchanged should they already exist.
349		 * @return StatusValue
350		 */
351		public function addWatchIgnoringRights(
352			UserIdentity $userIdentity,
353			PageReference $target,
354			?string $expiry = null
355		): StatusValue {
356			if ( !$this->isWatchable( $target ) ) {
357				return StatusValue::newFatal( 'watchlistnotwatchable' );
358			}
359	
360			$wikiPage = $this->wikiPageFactory->newFromTitle( $target );
361			$title = $wikiPage->getTitle();
362	
363			$status = Status::newFatal( 'hookaborted' );
364			// TODO: broaden the interface on these hooks to accept PageReference
365			if ( $this->hookRunner->onWatchArticle( $userIdentity, $wikiPage, $status, $expiry ) ) {
366				$status = StatusValue::newGood();
367				$this->watchedItemStore->addWatch( $userIdentity, $this->getSubjectPage( $title ), $expiry );
368				if ( $this->nsInfo->canHaveTalkPage( $title ) ) {
369					$this->watchedItemStore->addWatch( $userIdentity, $this->getTalkPage( $title ), $expiry );
370				}
371				$this->hookRunner->onWatchArticleComplete( $userIdentity, $wikiPage );
372			}
373	
374			// eventually user_touched should be factored out of User and this should be replaced
375			$user = $this->userFactory->newFromUserIdentity( $userIdentity );
376			$user->invalidateCache();
377	
378			return $status;
379		}
