492		/**
493		 * Watch or unwatch a page, calling watch/unwatch hooks as appropriate.
494		 * Checks before watching or unwatching to see if the page is already in the requested watch
495		 * state and if the expiry is the same so it does not act unnecessarily.
496		 *
497		 * @param bool $watch Whether to watch or unwatch the page
498		 * @param Authority $performer who is watching/unwatching
499		 * @param PageReference $target Page to watch/unwatch
500		 * @param string|null $expiry Optional expiry timestamp in any format acceptable to wfTimestamp(),
501		 *   null will not create expiries, or leave them unchanged should they already exist.
502		 * @return StatusValue
503		 * @since 1.37
504		 */
505		public function setWatch(
506			bool $watch,
507			Authority $performer,
508			PageReference $target,
509			?string $expiry = null
510		): StatusValue {
511			// User must be registered, and (T371091) not a temp user
512			if ( !$performer->getUser()->isRegistered() || $performer->isTemp() ) {
513				return StatusValue::newGood();
514			}
515	
516			// User must be either changing the watch state or at least the expiry.
517	
518			// Only call addWatchIgnoringRights() or removeWatch() if there's been a change in the watched status.
519			$oldWatchedItem = $this->watchedItemStore->getWatchedItem( $performer->getUser(), $target );
520			$changingWatchStatus = (bool)$oldWatchedItem !== $watch;
521			if ( $oldWatchedItem && $expiry !== null ) {
522				// If there's an old watched item, a non-null change to the expiry requires an UPDATE.
523				$oldWatchPeriod = $oldWatchedItem->getExpiry() ?? 'infinity';
524				$changingWatchStatus = $changingWatchStatus ||
525					$oldWatchPeriod !== ExpiryDef::normalizeExpiry( $expiry, TS::MW );
526			}
527	
528			if ( $changingWatchStatus ) {
529				// If the user doesn't have 'editmywatchlist', we still want to
530				// allow them to add but not remove items via edits and such.
531				if ( $watch ) {
532					return $this->addWatchIgnoringRights( $performer->getUser(), $target, $expiry );
533				} else {
534					return $this->removeWatch( $performer, $target );
535				}
536			}
537	
538			return StatusValue::newGood();
539		}
