14	/**
15	 * Service class for storage of watchlist labels.
16	 *
17	 * @since 1.46
18	 */
19	class WatchlistLabelStore {
20	
21		public const TABLE_WATCHLIST_LABEL = 'watchlist_label';
22		public const TABLE_WATCHLIST_LABEL_MEMBER = 'watchlist_label_member';
23	
24		public function __construct(
25			private IConnectionProvider $dbProvider,
26			private LoggerInterface $logger,
27			private Config $config
28		) {
29		}
