121		/**
122		 * Load a single watchlist label by ID.
123		 *
124		 * @param UserIdentity $user
125		 * @param int $id The watchlist_label ID.
126		 *
127		 * @return ?WatchlistLabel The label, or null if not found.
128		 */
129		public function loadById( UserIdentity $user, int $id ): ?WatchlistLabel {
130			return $this->loadByIds( $user, [ $id ] )[0] ?? null;
131		}
