208		/**
209		 * Get counts of all items with the given labels.
210		 *
211		 * @param int[] $labelIds
212		 *
213		 * @return array Keys are the label ID, values the integer count.
214		 */
215		public function countItems( array $labelIds ): array {
216			if ( count( $labelIds ) === 0 ) {
217				return [];
218			}
219			$select = $this->dbProvider->getReplicaDatabase()->newSelectQueryBuilder();
220			$results = $select->table( self::TABLE_WATCHLIST_LABEL_MEMBER )
221				->fields( [ 'wlm_label', 'item_count' => 'COUNT(wlm_label)' ] )
222				->where( [ 'wlm_label' => $labelIds ] )
223				->groupBy( [ 'wlm_label' ] )
224				->caller( __METHOD__ )
225				->fetchResultSet();
226			$counts = array_combine( $labelIds, array_fill( 0, count( $labelIds ), 0 ) );
227			foreach ( $results as $result ) {
228				$counts[ $result->wlm_label ] = (int)$result->item_count;
229			}
230			return $counts;
231		}
232	
233		/**
234		 * Get the current total count of a user's watchlist labels.
235		 *
236		 * @param UserIdentity $user
237		 *
238		 * @return int
239		 */
240		public function countAllForUser( UserIdentity $user ): int {
241			$select = $this->dbProvider->getReplicaDatabase()->newSelectQueryBuilder();
242			return (int)$select->table( self::TABLE_WATCHLIST_LABEL )
243				->field( 'COUNT(*)' )
244				->where( [ 'wll_user' => $user->getId() ] )
245				->caller( __METHOD__ )
246				->fetchField();
247		}
